package com.coraline.tycoon;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraftforge.gametest.*;
@GameTestHolder("coraline") @PrefixGameTestTemplate(false)
public final class TycoonGameTests {
    private static ServerPlayer player(GameTestHelper h){var l=h.getLevel().getServer().overworld();var p=new ServerPlayer(l.getServer(),l,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"TycoonQA"));p.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(p.server,new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p);p.setPos(h.absolutePos(new BlockPos(2,2,2)).getCenter());return p;}
    private static void clean(ServerPlayer p){TycoonData.get(p.server).homes.remove(p.getUUID());TycoonNetwork.clear(p.getUUID());TycoonNativePlayers.remove(p);}
    @GameTest(template="empty") public static void realMainStoryResetPreservesTycoonLedgerAndPhysicalProperty(GameTestHelper t){var p=player(t);try{var h=TycoonWorld.home(p);h.state.putBoolean("Activated",true);h.state.putBoolean("PlatformBuilt",true);h.state.putLong("SoulEssence",27);h.state.putLong("PlacementAfter",72000);h.state.putLong("Agency",p.blockPosition().east(64).asLong());h.state.putBoolean("AgencyBuilt",true);h.milestone("first_inspection",50);var child=TycoonCare.generate(UUID.randomUUID());child.n.putString("Status","ACTIVE");h.residents.put(child.id,child);var at=t.absolutePos(new BlockPos(2,2,2));owned(p,"special_dimension_little_door",at);p.getInventory().setItem(0,TycoonWorld.bound(p,"orphanage_phone"));p.getInventory().setItem(1,new ItemStack(TycoonContent.VOID_POWER.get(),9));h.state.putInt("SkyTier",3);h.state.putInt("HouseTier",4);child.n.putDouble("Trustness",.37);child.n.putDouble("Suspicion",.44);var doll=new ItemStack(TycoonPhaseTwoContent.DOLL.get());doll.getOrCreateTag().putUUID("TycoonOwner",p.getUUID());doll.getTag().putUUID("Resident",child.id);doll.getTag().putUUID("Doll",UUID.randomUUID());p.getInventory().setItem(2,doll);var inventory=p.getInventory().save(new ListTag());var before=h.save();
        var run=com.coraline.rebirth.StoryRun.first(p.getUUID());run.finish(true);run.delivered(run.receipt());var details=run.details();details.putLong("Center",at.asLong());details.putLong("PortraitPosition",at.north().asLong());details.putUUID("Portrait",UUID.randomUUID());run.details(details);t.assertTrue(run.commit(UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),UUID.randomUUID(),new CompoundTag()),"Reset fixture failed to commit");
        while(run.phase()!=com.coraline.rebirth.StoryRun.Phase.RESETTING){var phase=run.phase();if(phase==com.coraline.rebirth.StoryRun.Phase.FIRST_THREAD||phase==com.coraline.rebirth.StoryRun.Phase.FINAL_THREAD)run.cut(p.getUUID(),run.session(),phase==com.coraline.rebirth.StoryRun.Phase.FIRST_THREAD);else{if(phase==com.coraline.rebirth.StoryRun.Phase.FIRST_DEATH||phase==com.coraline.rebirth.StoryRun.Phase.FINAL_DEATH)run.recordDeath(run.session(),phase==com.coraline.rebirth.StoryRun.Phase.FIRST_DEATH);run.advance(run.session(),phase,com.coraline.rebirth.StoryRun.Phase.values()[phase.ordinal()+1]);}}
        com.coraline.feast.MainStoryRebirth.reset(p,run);t.assertTrue(before.equals(h.save())&&inventory.equals(p.getInventory().save(new ListTag())),"Real main-story reset modified permanent tycoon state/items");t.assertTrue(p.server.overworld().getBlockState(at).is(TycoonContent.DOOR.get()),"Real reset removed the Special Door");t.assertTrue(TycoonData.load(TycoonData.get(p.server).save(new CompoundTag())).home(p.getUUID()).save().equals(before),"Preserved tycoon ledger failed reload");}finally{clean(p);}t.succeed();}
    @GameTest(template="empty") public static void unlockReceiptReconcilesOnlyMatchingPreparedOwnerIntent(GameTestHelper t){var p=player(t);try{var h=TycoonWorld.home(p);var receipt=UUID.randomUUID();h.state.putUUID("UnlockIntent",receipt);h.state.putBoolean("PlatformBuilt",true);TycoonCheckpoints.receipt(p,UUID.randomUUID());t.assertFalse(TycoonCheckpoints.reconcile(p)||h.active(),"Foreign receipt unlocked world");TycoonCheckpoints.receipt(p,receipt);t.assertTrue(TycoonCheckpoints.reconcile(p)&&h.active()&&h.xp()==50,"Consumed Weaver recovery lost unlock");t.assertFalse(TycoonCheckpoints.reconcile(p),"Recovery replayed milestone");t.assertTrue(h.xp()==50,"Recovered unlock granted duplicate XP");}finally{clean(p);}t.succeed();}
    private static void owned(ServerPlayer p,String id,BlockPos at){var l=p.server.overworld();l.setBlock(at,TycoonContent.BLOCKS.get(id).get().defaultBlockState(),2);var be=(TycoonBlockEntity)l.getBlockEntity(at);be.owner=p.getUUID();be.setChanged();if(!id.equals("special_dimension_little_door")){var f=TycoonWorld.home(p).state.getCompound("Furniture");f.putString(Long.toString(at.asLong()),id);TycoonWorld.home(p).state.put("Furniture",f);}else TycoonWorld.home(p).state.putLong("Entrance",at.asLong());}
    @GameTest(template="empty") public static void independentOwnersPersistentRegionsAndFutureCurrencyReceipts(GameTestHelper t){var data=new TycoonData();var a=data.home(UUID.randomUUID());var b=data.home(UUID.randomUUID());t.assertTrue(a.center().distSqr(b.center())>=1024*1024,"Owner regions collide");a.state.putBoolean("Activated",true);a.state.putLong("PlacementAfter",72000);t.assertTrue(a.milestone("inspection",50)&&!a.milestone("inspection",50)&&a.xp()==50,"Repeat milestone farm");t.assertTrue(a.creditSoul("future-receipt",12)&&!a.creditSoul("future-receipt",12),"Soul credit not idempotent");var saved=data.save(new CompoundTag());var loaded=TycoonData.load(saved);t.assertTrue(saved.equals(loaded.save(new CompoundTag())),"Owner world did not round-trip");t.assertTrue(loaded.home(a.owner).cooldown()==72000&&loaded.home(b.owner).cooldown()==0,"Per-owner placement clocks mixed");t.succeed();}
    @GameTest(template="empty") public static void invalidAndFullInventoryPurchasesNeverSpendAndPhoneIsOnce(GameTestHelper t){var p=player(t);TycoonNativePlayers.add(p);try{var h=TycoonWorld.home(p);h.state.putBoolean("Activated",true);p.getInventory().setItem(0,new ItemStack(TycoonContent.VOID_POWER.get(),32));for(int i=1;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));t.assertTrue(TycoonShop.buy(p,"orphan_bed").contains("Free")&&TycoonShop.count(p,TycoonContent.VOID_POWER.get())==32,"Full inventory ate currency");p.getInventory().setItem(5,ItemStack.EMPTY);t.assertTrue(TycoonShop.buy(p,"orphan_bed").startsWith("Purchased")&&TycoonShop.count(p,TycoonContent.VOID_POWER.get())==32-TycoonConfig.PRICES.get("orphan_bed").get(),"Actual upgrade cost/delivery wrong");t.assertTrue(TycoonWorld.owned(p,p.getInventory().getItem(5)),"Upgrade not owner-bound");t.assertTrue(TycoonShop.buy(p,"unknown").contains("unavailable"),"Arbitrary purchase accepted");p.getInventory().setItem(6,ItemStack.EMPTY);TycoonShop.phone(p);var phone=p.getInventory().getItem(6).copy();t.assertTrue(TycoonWorld.validPhone(p,phone),"Issued phone invalid");TycoonShop.phone(p);t.assertTrue(TycoonShop.count(p,TycoonContent.PHONE.get())==1,"Free phone duplicated");}finally{clean(p);}t.succeed();}
    @GameTest(template="empty") public static void generatedTraitsNeedsAndNeglectHaveCorrectDirection(GameTestHelper t){var first=TycoonCare.generate(new UUID(0,0));var second=TycoonCare.generate(UUID.randomUUID());t.assertTrue(!first.name().equals(second.name()),"Generated names identical");t.assertTrue(!first.n.getCompound("Traits").equals(second.n.getCompound("Traits")),"Identical personalities");double hunger=first.need("Hunger"),thirst=first.need("Thirst");TycoonCare.needs(first,1200,true);t.assertTrue(first.need("Hunger")<hunger&&first.need("Thirst")<thirst&&first.need("Hunger")>80,"Needs decay reversed/too rapid");first.need("Hunger",0);first.need("Thirst",0);first.need("Neglect",50);TycoonCare.needs(first,1200,false);t.assertTrue(first.need("Neglect")>50,"Deprivation reduced neglect");TycoonCare.feed(first,new ItemStack(Items.BREAD),true);t.assertTrue(first.need("Hunger")>0&&first.need("Neglect")<54,"Manual care failed");t.assertTrue(TycoonFoodQuality.tier(new ItemStack(Items.POISONOUS_POTATO))==TycoonFoodQuality.Tier.TERRIBLE&&!TycoonBlockEntity.food(new ItemStack(Items.STICK)),"Unsafe food not classified Terrible, or inedible item accepted");t.succeed();}
    @GameTest(template="empty") public static void movingDoorPreservesWorldAndStaleCapabilitiesCannotPlace(GameTestHelper t){var p=player(t);try{var h=TycoonWorld.home(p);var at=t.absolutePos(new BlockPos(2,2,2));var l=p.serverLevel();l.setBlock(at.below(),Blocks.STONE.defaultBlockState(),2);l.setBlock(at.above(),Blocks.AIR.defaultBlockState(),2);var bed=at.west(2);l.setBlock(bed,Blocks.BLUE_BED.defaultBlockState(),2);p.setRespawnPosition(l.dimension(),bed,0,false,false);t.assertTrue(TycoonWorld.giveDoor(p,false),"Could not grant entrance");var original=p.getInventory().getItem(0).copy();t.assertTrue(TycoonWorld.canPlace(p,"special_dimension_little_door",at,original),"Valid registered-bed placement rejected");owned(p,"special_dimension_little_door",at);h.state.putBoolean("Activated",true);h.state.putLong("SoulEssence",13);t.assertTrue(TycoonWorld.pickup(p,at),"Owner pickup failed");t.assertTrue(h.active()&&h.state.getLong("SoulEssence")==13&&h.entrance()==null,"Moving door erased progress");t.assertFalse(TycoonWorld.canPlace(p,"special_dimension_little_door",at,original),"Stale copied capability can place");var helper=player(t);try{t.assertFalse(TycoonWorld.canPlace(helper,"special_dimension_little_door",at,p.getInventory().getItem(1)),"Foreign player can claim entrance");}finally{clean(helper);}t.assertFalse(com.coraline.feast.MainStoryRebirth.retireStack(p.getInventory().getItem(1),p.getUUID(),UUID.randomUUID(),0),"Story reset retires distinct special door type");}finally{clean(p);}t.succeed();}
    @GameTest(template="empty") public static void exactPlatformBuiltOnceAndWeaverFailurePreservesInventory(GameTestHelper t){var p=player(t);try{var h=TycoonWorld.home(p);t.assertTrue(p.server.getLevel(TycoonWorld.KEY)!=null,"Personal data-driven dimension missing");t.assertTrue(TycoonWorld.prepare(p),"8x8 platform unavailable");var l=p.server.getLevel(TycoonWorld.KEY);int floor=0;for(int x=-5;x<=4;x++)for(int z=-5;z<=4;z++)if(l.getBlockState(h.center().offset(x,-1,z)).is(TycoonContent.FOUNDATION.get()))floor++;t.assertTrue(floor==64,"Initial platform is not exactly64 cells");var at=h.center().offset(2,0,2);l.setBlock(at,Blocks.GOLD_BLOCK.defaultBlockState(),2);TycoonWorld.prepare(p);t.assertTrue(l.getBlockState(at).is(Blocks.GOLD_BLOCK),"Repeated preparation overwrote player work");p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(TycoonContent.WEAVER.get()));t.assertFalse(TycoonWorld.activate(p,p.blockPosition()),"Non-owned story door activated");t.assertTrue(p.getMainHandItem().getCount()==1,"Failed activation consumed Weaver");}finally{clean(p);}t.succeed();}
    @GameTest(template="empty") public static void furnitureInventoriesAndFiniteWaterSurviveNbt(GameTestHelper t){var p=player(t);try{var at=t.absolutePos(new BlockPos(2,2,2));owned(p,"orphan_fridge",at);var be=(TycoonBlockEntity)p.serverLevel().getBlockEntity(at);be.setItem(0,new ItemStack(Items.BREAD,7));var saved=be.saveWithFullMetadata();var copy=new TycoonBlockEntity(at,be.getBlockState());copy.load(saved);t.assertTrue(copy.getItem(0).getCount()==7&&p.getUUID().equals(copy.owner),"Real food inventory/owner lost on reload");owned(p,"water_station",at);var water=(TycoonBlockEntity)p.serverLevel().getBlockEntity(at);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,new ItemStack(Items.WATER_BUCKET));water.refill(p);t.assertTrue(water.water==8&&p.getMainHandItem().is(Items.BUCKET),"Water refill isn't a real transaction");water.water--;t.assertTrue(water.water==7,"Water created unlimited servings");}finally{clean(p);}t.succeed();}
    @GameTest(template="empty") public static void agencyNeverOverwritesBuildAndCandidatePoolPersists(GameTestHelper t){var p=player(t);try{var at=t.absolutePos(new BlockPos(2,2,2));p.serverLevel().setBlock(at,Blocks.DIAMOND_BLOCK.defaultBlockState(),2);t.assertFalse(TycoonAgency.clearSite(p.serverLevel(),at),"Agency approves occupied footprint");var h=TycoonWorld.home(p);var a=TycoonAgency.candidates(h).stream().map(r->r.id).collect(java.util.stream.Collectors.toSet());var b=TycoonAgency.candidates(h).stream().map(r->r.id).collect(java.util.stream.Collectors.toSet());t.assertTrue(a.size()==3&&a.equals(b),"Phone rerolls candidates");var saved=TycoonData.get(p.server).save(new CompoundTag());t.assertTrue(TycoonData.load(saved).home(p.getUUID()).state.getCompound("Candidates").equals(h.state.getCompound("Candidates")),"Candidate identities lost on save");}finally{clean(p);}t.succeed();}
}
